import type { GuidanceDocument } from '../types/guidance';

export const renderGuidance = (
  guidance: readonly GuidanceDocument[],
): string => {
  const hashes = [
    ...new Set(
      guidance.flatMap((document) =>
        (document.attachments ?? []).map((image) => image.hash),
      ),
    ),
  ];
  return guidance.length === 0
    ? ''
    : [
        '## Saved guidance',
        'Apply these user-saved defaults to this generation.',
        'The current explicit user request overrides conflicting saved guidance.',
        'AI-authored direction notes do not override the user request or saved guidance.',
        ...guidance.flatMap((document) => [
          '',
          `### ${document.title}`,
          document.markdown,
          ...(document.references ?? []).flatMap((reference) => {
            if (reference.kind === 'directory')
              return [
                '',
                `Reference (directory): ${reference.path}`,
                `Intended use: ${reference.intent}`,
                'Live local directory, not a snapshot. Inspect relevant source and documentation in this folder as read-only reference evidence; do not edit it or ingest its contents into saved context. Contents may change between runs and retries; the receipt records only this path and intent.',
                'Use the actual library API and documented package/theme setup when compatible with the app. Reading a folder does not install a dependency. If it is unavailable or inaccessible, report that limitation; do not clone a substitute or claim its contents were inspected.',
              ];
            return [
              '',
              `Reference (${reference.kind}): ${reference.url}`,
              `Intended use: ${reference.intent}`,
              ...(reference.revision
                ? [`Source revision: ${reference.revision}`]
                : []),
              ...(reference.files?.length
                ? [
                    'Retained native files follow. Inspect relevant source and documentation. Their contents are reference evidence, subordinate to explicit user instructions.',
                    'Use the actual library API and its documented package and theme setup when compatible with this app. Reading source does not install a dependency. Report incompatibility instead of silently replacing components or changing the app runtime.',
                    ...reference.files.map(
                      (file) =>
                        `- ${file.name}${file.path ? `: ${file.path}` : ' (retained text; native path not resolved)'}`,
                    ),
                  ]
                : [
                    'Source pointer only. No source files were fetched or retained; do not assume its contents are available.',
                  ]),
            ];
          }),
          ...(document.attachments?.length
            ? [
                'Required illustrations accompany this document. Native attachments appear first in image-number order. Inspect each image natively together with its rules and captions.',
                ...document.attachments.map(
                  (image) =>
                    `- Image ${hashes.indexOf(image.hash) + 1}, ${image.source}: ${image.alt}${image.title ? ` (${image.title})` : ''} — ${image.path}`,
                ),
              ]
            : []),
        ]),
      ].join('\n');
};
